fn get_column(input: &Vec<Vec<i8>>, j: usize, m: usize, n: usize) -> Vec<i8> {
    // Precondition: input.len() == n and for each row input[i].len() == m
    let mut col = Vec::with_capacity(n);
    for i in 0..n {
        col.push(input[i][j]);
    }
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    // Precondition: input.len() == n and each row has length m
    let mut result = Vec::with_capacity(m);
    for j in 0..m {
        result.push(get_column(&input, j, m, n));
    }
    result
}